import { noopFn } from "../../internal/noopFn.js";
import { usePrefix } from "../../internal/usePrefix.js";
import { IconButton } from "../IconButton/index.js";
import { forwardRef, useState } from "react";
import cx from "classnames";
import PropTypes from "prop-types";
import { jsx } from "react/jsx-runtime";
//#region src/components/Switch/IconSwitch.tsx
/**
* Copyright IBM Corp. 2016, 2023
*
* This source code is licensed under the Apache-2.0 license found in the
* LICENSE file in the root directory of this source tree.
*/
const IconSwitch = forwardRef((props, ref) => {
	const { align, children, className, disabled, enterDelayMs, index, leaveDelayMs = 0, name, onClick = noopFn, onKeyDown = noopFn, selected = false, size, text, ...other } = props;
	const prefix = usePrefix();
	const [isHovered, setIsHovered] = useState(false);
	const handleClick = (event) => {
		event.preventDefault();
		onClick({
			index,
			name,
			text
		});
	};
	const handleKeyDown = (event) => {
		const key = event.key || event.which;
		onKeyDown({
			index,
			name,
			text,
			key
		});
	};
	const handleMouseEnter = () => {
		setIsHovered(true);
	};
	const handleMouseLeave = () => {
		setIsHovered(false);
	};
	const classes = cx(className, `${prefix}--content-switcher-btn`, { [`${prefix}--content-switcher--selected`]: selected });
	const iconButtonClasses = cx(`${prefix}--content-switcher-popover__wrapper`, {
		[`${prefix}--content-switcher-popover--selected`]: selected,
		[`${prefix}--content-switcher-popover--disabled`]: disabled
	});
	return /* @__PURE__ */ jsx(IconButton, {
		label: text,
		type: "button",
		ref,
		role: "tab",
		tabIndex: selected || isHovered ? 0 : -1,
		onMouseEnter: handleMouseEnter,
		onMouseLeave: handleMouseLeave,
		onFocus: handleMouseEnter,
		onBlur: handleMouseLeave,
		"aria-selected": selected,
		"aria-label": text,
		wrapperClasses: iconButtonClasses,
		...other,
		align,
		className: classes,
		disabled,
		enterDelayMs,
		leaveDelayMs,
		onClick: handleClick,
		onKeyDown: handleKeyDown,
		size,
		children
	});
});
IconSwitch.displayName = "IconSwitch";
IconSwitch.propTypes = {
	/**
	* Specify how the trigger should align with the tooltip
	*/
	align: PropTypes.oneOf([
		"top",
		"top-left",
		"top-right",
		"bottom",
		"bottom-left",
		"bottom-right",
		"left",
		"right"
	]),
